597	  </div>
598	
599	  <p class="empty-note" id="emptyNote">No assets in this stage yet.</p>
600	
601	  <footer>
602	    <b>MewGuard</b> — sentimental-design asset kit · <b id="progress">12 of 40</b> planned assets ·
603	    all assets are pure inline SVG + CSS, dependency-free, and honor <code>prefers-reduced-motion</code> — toggle
604	    <b>Reduce motion</b> to preview that still fallback. <b>Copy SVG</b> drops self-animating markup onto your clipboard,
605	    or hit the <b>download</b> button to save a standalone <code>.svg</code> file — both embed their own animation
606	    <code>&lt;style&gt;</code>, so the asset stays alive the moment you paste or open it. Palette and tone follow the
607	    app theme in <code>cat_toxin_app/constants/colors.ts</code>.
608	  </footer>
609	</div>
610	
611	<div class="toast" id="toast" role="status" aria-live="polite">Copied!</div>
612	
613	<script>
614	(function () {
615	  // The minimal animation stylesheet each asset depends on. Embedded inside the
616	  // copied <svg> so the asset stays self-animating when dropped into any project.
617	  var ANIM_CSS = [
618	    '@keyframes float{0%,100%{transform:translateY(0)}50%{transform:translateY(-7px)}}',
619	    '@keyframes blink{0%,92%,100%{transform:scaleY(1)}96%{transform:scaleY(.1)}}',
620	    '@keyframes sway{0%,100%{transform:rotate(-4deg)}50%{transform:rotate(4deg)}}',
621	    '@keyframes pop{0%{transform:scale(0);opacity:0}60%{transform:scale(1.15);opacity:1}100%{transform:scale(1)}}',
622	    '@keyframes draw{to{stroke-dashoffset:0}}',
623	    '@keyframes confetti{0%{transform:translateY(0) rotate(0);opacity:1}100%{transform:translateY(-46px) rotate(220deg);opacity:0}}',
624	    '@keyframes spin{to{transform:rotate(360deg)}}',
625	    '@keyframes pulse{0%,100%{transform:scale(1);opacity:.9}50%{transform:scale(1.12);opacity:.5}}',
626	    '@keyframes wiggle{0%,100%{transform:rotate(0)}25%{transform:rotate(8deg)}75%{transform:rotate(-8deg)}}',
627	    '@keyframes orbit{to{transform:rotate(-360deg)}}',
628	    '@keyframes rise{0%,100%{transform:translateY(0)}50%{transform:translateY(-4px)}}',
629	    '@keyframes twinkle{0%,100%{opacity:.2;transform:scale(.6)}50%{opacity:1;transform:scale(1)}}',
630	    '@keyframes heartbeat{0%,100%{transform:scale(1)}15%{transform:scale(1.13)}30%{transform:scale(1)}45%{transform:scale(1.08)}}',
631	    '@keyframes purr{0%,100%{transform:translateX(0)}25%{transform:translateX(-.8px)}75%{transform:translateX(.8px)}}',
632	    '@keyframes tailwag{0%,100%{transform:rotate(-10deg)}50%{transform:rotate(14deg)}}',
633	    '.a-float{animation:float 4s ease-in-out infinite;transform-origin:center}',
634	    '.a-blink{animation:blink 5s ease-in-out infinite;transform-origin:center}',
635	    '.a-sway{animation:sway 4.5s ease-in-out infinite;transform-origin:50% 90%}',
636	    '.a-pop{animation:pop .7s cubic-bezier(.2,1.3,.4,1) both}',
637	    '.a-spin{animation:spin 1.4s linear infinite;transform-origin:center}',
638	    '.a-pulse{animation:pulse 2.6s ease-in-out infinite;transform-origin:center}',
639	    '.a-wiggle{animation:wiggle 3.5s ease-in-out infinite;transform-origin:50% 80%}',
640	    '.a-orbit{animation:orbit 6s linear infinite;transform-origin:center}',
641	    '.a-rise{animation:rise 3s ease-in-out infinite;transform-origin:center}',
642	    '.a-twinkle{animation:twinkle 2s ease-in-out infinite;transform-origin:center}',
643	    '.a-heartbeat{animation:heartbeat 2.4s ease-in-out infinite;transform-origin:center}',
644	    '.a-purr{animation:purr .25s ease-in-out infinite;transform-origin:center}',
645	    '.a-tailwag{animation:tailwag 2.2s ease-in-out infinite;transform-origin:0% 100%}',
646	    '.draw{stroke-dasharray:90;stroke-dashoffset:90;animation:draw 1s ease-out .25s forwards}',
647	    '.conf{animation:confetti 1.3s ease-out infinite}',
648	    '.conf:nth-child(odd){animation-duration:1.6s}',
649	    '@media (prefers-reduced-motion:reduce){.a-float,.a-blink,.a-sway,.a-pop,.a-spin,.a-pulse,.a-wiggle,.a-orbit,.a-rise,.a-twinkle,.a-heartbeat,.a-purr,.a-tailwag,.conf{animation:none}.draw{stroke-dashoffset:0}}'
650	  ].join('');
651	
652	  // Build standalone, self-animating SVG markup for one card's stage <svg>.
653	  function buildSvg(svg) {
654	    var clone = svg.cloneNode(true);
655	    var style = document.createElementNS('http://www.w3.org/2000/svg', 'style');
656	    style.textContent = ANIM_CSS;
657	    clone.insertBefore(style, clone.firstChild);
658	    if (!clone.getAttribute('xmlns')) clone.setAttribute('xmlns', 'http://www.w3.org/2000/svg');
659	    return clone.outerHTML.replace(/></g, '>\n<');
660	  }
661	
662	  var toast = document.getElementById('toast'), toastTimer;
663	  function showToast(msg) {
664	    toast.textContent = msg;
665	    toast.classList.add('show');
666	    clearTimeout(toastTimer);
667	    toastTimer = setTimeout(function () { toast.classList.remove('show'); }, 1800);
668	  }
669	
670	  var COPY_IC = '<svg class="ic" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="9" y="9" width="11" height="11" rx="2"/><path d="M5 15V5a2 2 0 0 1 2-2h10"/></svg>';
671	  var DONE_IC = '<svg class="ic" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><path d="M5 13l4 4L19 7"/></svg>';
672	  var DL_IC   = '<svg class="ic" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 3v12"/><path d="M7 11l5 5 5-5"/><path d="M5 20h14"/></svg>';
673	  var REPLAY_IC = '<svg class="ic" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 12a9 9 0 1 1-3-6.7"/><path d="M21 3v5h-5"/></svg>';
674	
675	  // Restart every animation in an asset's <svg> from frame 0 (one-shots re-play, infinites re-sync).
676	  function replayAnimations(svg) {
677	    svg.classList.add('anim-off');
678	    void svg.getBoundingClientRect();   // force reflow so the "animation:none" takes effect
679	    svg.classList.remove('anim-off');
680	  }
681	
682	  // "All clear" -> "all-clear" for a friendly .svg filename
683	  function slugify(name) {
684	    return (name || 'asset').toLowerCase()
685	      .replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '') || 'asset';
686	  }
687	
688	  // Save a standalone .svg document (self-animating markup + XML prolog) to disk.
689	  function downloadSvg(markup, filename) {
690	    var doc = '<?xml version="1.0" encoding="UTF-8"?>\n' + markup;
691	    var blob = new Blob([doc], { type: 'image/svg+xml' });
692	    var url = URL.createObjectURL(blob);
693	    var a = document.createElement('a');
694	    a.href = url; a.download = filename;
695	    document.body.appendChild(a); a.click(); document.body.removeChild(a);
696	    setTimeout(function () { URL.revokeObjectURL(url); }, 1000);
697	  }
698	
699	  function fallbackCopy(text) {
700	    var ta = document.createElement('textarea');
701	    ta.value = text; ta.style.position = 'fixed'; ta.style.opacity = '0';
702	    document.body.appendChild(ta); ta.select();
703	    var ok = false; try { ok = document.execCommand('copy'); } catch (e) {}
704	    document.body.removeChild(ta); return ok;
705	  }
706	
707	  document.querySelectorAll('.card').forEach(function (card) {
708	    var svg = card.querySelector('.stage svg');
709	    if (!svg) return;
710	    var name = (card.querySelector('.name') || {}).textContent || 'asset';
711	
712	    // Replay control on the stage — re-runs the asset's animation for inspection.
713	    var stage = card.querySelector('.stage');
714	    if (stage) {
715	      var replay = document.createElement('button');
716	      replay.type = 'button';
717	      replay.className = 'replay-btn';
718	      replay.innerHTML = REPLAY_IC + '<span>Replay</span>';
719	      replay.setAttribute('aria-label', 'Replay the ' + name + ' animation');
720	      replay.addEventListener('click', function () { replayAnimations(svg); });
721	      stage.appendChild(replay);
722	    }
723	
724	    var btn = document.createElement('button');
725	    btn.type = 'button';
726	    btn.className = 'copy-btn';
727	    btn.innerHTML = COPY_IC + '<span>Copy SVG</span>';
728	    btn.setAttribute('aria-label', 'Copy SVG markup for ' + name);
729	
730	    btn.addEventListener('click', function () {
731	      var markup = buildSvg(svg);
732	      var done = function () {
733	        btn.classList.add('done');
734	        btn.innerHTML = DONE_IC + '<span>Copied!</span>';
735	        showToast('SVG copied — paste it anywhere');
736	        setTimeout(function () {
737	          btn.classList.remove('done');
738	          btn.innerHTML = COPY_IC + '<span>Copy SVG</span>';
739	        }, 1800);
740	      };
741	      if (navigator.clipboard && navigator.clipboard.writeText) {
742	        navigator.clipboard.writeText(markup).then(done, function () {
743	          if (fallbackCopy(markup)) done(); else showToast('Copy failed — select manually');
744	        });
745	      } else {
746	        if (fallbackCopy(markup)) done(); else showToast('Copy failed — select manually');
747	      }
748	    });
749	
750	    var dl = document.createElement('button');
751	    dl.type = 'button';
752	    dl.className = 'dl-btn';
753	    dl.innerHTML = DL_IC;
754	    dl.setAttribute('aria-label', 'Download ' + name + ' as an SVG file');
755	    dl.title = 'Download .svg';
756	    dl.addEventListener('click', function () {
757	      downloadSvg(buildSvg(svg), slugify(name) + '.svg');
758	      showToast('Downloaded ' + slugify(name) + '.svg');
759	    });
760	
761	    var actions = document.createElement('div');
762	    actions.className = 'actions';
763	    actions.appendChild(btn);
764	    actions.appendChild(dl);
765	    card.querySelector('.body').appendChild(actions);
766	  });
767	
768	  // ---- Journey-stage filtering ----
769	  var cards = Array.prototype.slice.call(document.querySelectorAll('.card'));
770	  var chips = Array.prototype.slice.call(document.querySelectorAll('.filterbar .chip'));
771	  var countEl = document.getElementById('fbCount');
772	  var emptyNote = document.getElementById('emptyNote');
773	
774	  function applyFilter(filter) {
775	    var shown = 0;
776	    cards.forEach(function (card) {
777	      var match = filter === 'all' || card.getAttribute('data-cat') === filter;
778	      card.classList.toggle('hide', !match);
779	      if (match) shown++;
780	    });
781	    chips.forEach(function (chip) {
782	      chip.setAttribute('aria-pressed', String(chip.getAttribute('data-filter') === filter));
783	    });
784	    countEl.textContent = shown + (shown === 1 ? ' asset' : ' assets');
785	    emptyNote.style.display = shown === 0 ? 'block' : 'none';
786	  }
787	
788	  chips.forEach(function (chip) {
789	    chip.addEventListener('click', function () { applyFilter(chip.getAttribute('data-filter')); });
790	  });
791	
792	  // ---- Global motion toggle (freeze/resume all asset animations) ----
793	  var motionBtn = document.getElementById('motionToggle');
794	  if (motionBtn) {
795	    motionBtn.addEventListener('click', function () {
796	      var paused = document.body.classList.toggle('motion-paused');
797	      motionBtn.setAttribute('aria-pressed', String(paused));
798	      motionBtn.setAttribute('aria-label', paused ? 'Resume all asset animations' : 'Pause all asset animations');
799	    });
800	  }
801	
802	  // ---- Dark-stage preview toggle (flip every stage to a dark product surface) ----
803	  var stageBtn = document.getElementById('stageToggle');
804	  if (stageBtn) {
805	    stageBtn.addEventListener('click', function () {
806	      var dark = document.body.classList.toggle('stage-dark');
807	      stageBtn.setAttribute('aria-pressed', String(dark));
808	      stageBtn.setAttribute('aria-label', dark ? 'Preview assets on a light surface' : 'Preview assets on a dark surface');
809	    });
810	  }
811	
812	  // ---- Reduce-motion preview toggle (force the static prefers-reduced-motion fallback) ----
813	  var reduceBtn = document.getElementById('reduceToggle');
814	  if (reduceBtn) {
815	    reduceBtn.addEventListener('click', function () {
816	      var reduced = document.body.classList.toggle('motion-reduced');
817	      reduceBtn.setAttribute('aria-pressed', String(reduced));
818	      reduceBtn.setAttribute('aria-label', reduced ? 'Restore full motion' : 'Preview the reduced-motion fallback');
819	    });
820	  }
821	})();
822	</script>
823	</body>
824	</html>
